-- Atuacao em todo o Brasil: antes so existiam os 853 municipios de MG.
-- Nome de cidade se repete entre estados (ex: Bom Jesus), entao a
-- unicidade passa a ser nome + UF. Os slugs de MG ficam como estavam
-- (/cidade/ilicinea continua valendo); os outros estados levam a UF no
-- fim (ex: sao-paulo-sp). Fonte: IBGE, servicodados.ibge.gov.br.
ALTER TABLE cities
  ADD COLUMN IF NOT EXISTS uf CHAR(2) NOT NULL DEFAULT 'MG' AFTER name,
  DROP INDEX IF EXISTS uq_cities_name,
  ADD UNIQUE INDEX IF NOT EXISTS uq_cities_name_uf (name, uf);

ALTER TABLE professional_profiles
  ADD COLUMN IF NOT EXISTS uf CHAR(2) NOT NULL DEFAULT 'MG' AFTER city;

